package com.digitalbase.ticketing.dto;import lombok.Builder;import lombok.Data;import java.time.Instant;@Data@Builderpublic class ClientProductDetailResponse {    private String productName;    private String productDescription;    private String status;    private SlaDetails slaDetails;    private SystemMetadata metadata;    @Data @Builder    public static class SlaDetails {        private int totalSlaHours;        private int remainingHours;        private int remainingMinutes;        private int usedHours;        private int usedMinutes;        private int extraHours;        private int extraMinutes;        private long daysRemaining;        private Instant planEndDate;    }    @Data @Builder    public static class SystemMetadata {        private String productType;        private String supportPlan;        private Instant purchasedDate;        private Instant planEndDate;    }}